import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int at_times = 0;
        String input_str = scanner.nextLine();
        String buffer = "";
        List<String> output_strings = new ArrayList<>();

        if (!input_str.isEmpty()) {
            buffer += input_str.charAt(0);
            output_strings.add(buffer);
        }

        int i = 1;
        while (i + 1 < input_str.length()) {
            String three_chars = "";
            String two_chars = "";

            if (i + 2 < input_str.length()) {
                three_chars = input_str.substring(i, i + 3);
            }
            if (i + 1 < input_str.length()) {
                two_chars = input_str.substring(i, i + 2);
            }

            if (three_chars.equals("dot")) {
                buffer += '.';
                for (int j = 0; j < output_strings.size(); j++) {
                    output_strings.set(j, output_strings.get(j) + ".");
                }
                i += 3;
            } else if (two_chars.equals("at")) {
                at_times++;
                for (int j = 0; j < at_times - 1; j++) {
                    String s = output_strings.get(j);
                    output_strings.set(j, s + "at");
                }
                for (int j = at_times - 1; j < output_strings.size(); j++) {
                    String s = output_strings.get(j);
                    output_strings.set(j, s + "@");
                }
                buffer += input_str.charAt(i);
                buffer += input_str.charAt(i + 1);
                output_strings.add(buffer);
                i += 2;
            } else {
                buffer += input_str.charAt(i);
                for (int j = 0; j < output_strings.size(); j++) {
                    output_strings.set(j, output_strings.get(j) + input_str.charAt(i));
                }
                i++;
            }
        }

        if (!input_str.isEmpty()) {
            char last_char = input_str.charAt(input_str.length() - 1);
            for (int j = 0; j < output_strings.size(); j++) {
                output_strings.set(j, output_strings.get(j) + last_char);
            }
        }

        Collections.sort(output_strings);
        System.out.print(output_strings.get(0));
        scanner.close();
    }
}
